package com.nextaicommerce.platform.web;
import com.nextaicommerce.platform.shopify.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpSession;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.web.servlet.mvc.support.RedirectAttributesModelMap;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.assertj.core.api.Assertions.*;
class ShopifyCatalogueInitializationTest {
 @Test void verifiedInstalledProductPermissionAutomaticallyEnqueuesWithoutAcknowledgement(){var repo=mock(WorkspaceAccessRepository.class);var service=mock(ShopifyConnectionService.class);var access=mock(ShopifyConnectionAccess.class);var jobs=mock(ShopifyCatalogJobs.class);var worker=mock(ShopifyCatalogWorker.class);var controller=new ShopifyConnectionController(repo,service,access);ReflectionTestUtils.setField(controller,"catalogueJobs",jobs);ReflectionTestUtils.setField(controller,"catalogueWorker",worker);UUID tenant=new UUID(0,1),connection=new UUID(0,2),job=new UUID(0,3);var session=new MockHttpSession();session.setAttribute(AccountSelectionController.TENANT_ID,tenant);var actor=new UsernamePasswordAuthenticationToken("operator","");when(jobs.enabled()).thenReturn(true);when(service.setupState(tenant,connection)).thenReturn(new ShopifyConnectionService.SetupState(true,true));when(jobs.enqueue(tenant,connection,"operator")).thenReturn(job);var flash=new RedirectAttributesModelMap();assertThat(controller.permissions(connection,session,actor,flash)).isEqualTo("redirect:/app/connections");verify(service).refreshPermissions(eq(tenant),eq(connection),any(Runnable.class));verify(jobs).enqueue(tenant,connection,"operator");verify(worker).start(tenant,connection,job);assertThat(flash.getFlashAttributes().get("connectionSuccess").toString()).contains("background","Orders are not enabled");}
 @Test void missingPermissionDoesNotEnqueueOrPretendOrdersAreEnabled(){var service=mock(ShopifyConnectionService.class);var controller=new ShopifyConnectionController(mock(WorkspaceAccessRepository.class),service,mock(ShopifyConnectionAccess.class));var jobs=mock(ShopifyCatalogJobs.class);var worker=mock(ShopifyCatalogWorker.class);ReflectionTestUtils.setField(controller,"catalogueJobs",jobs);ReflectionTestUtils.setField(controller,"catalogueWorker",worker);var tenant=new UUID(0,1);var connection=new UUID(0,2);var session=new MockHttpSession();session.setAttribute(AccountSelectionController.TENANT_ID,tenant);when(jobs.enabled()).thenReturn(true);when(service.setupState(tenant,connection)).thenReturn(new ShopifyConnectionService.SetupState(true,false));var flash=new RedirectAttributesModelMap();controller.verify(connection,session,new UsernamePasswordAuthenticationToken("operator",""),flash);verify(jobs,never()).enqueue(any(),any(),any());verifyNoInteractions(worker);assertThat(flash.getFlashAttributes().get("connectionSuccess").toString()).contains("Approve product access");}
 @Test void shopifyProgressDoesNotBorrowAmazonStepsOrFabricatePercent(){var state=new WorkspaceAccessRepository.SyncStatusView(new UUID(0,1),"Shop","RUNNING",0,"SHOPIFY_CATALOG_VARIANTS","Reading variants",java.time.Instant.EPOCH);assertThat(state.shopify()).isTrue();assertThat(state.stagePosition()).isEqualTo("Products and variants");assertThat(state.estimatedTimeRemaining()).isEqualTo("Continues in the background");assertThat(state.terminal()).isFalse();var stopped=new WorkspaceAccessRepository.SyncStatusView(new UUID(0,1),"Shop","COMPLETED_WITH_WARNINGS",0,"SHOPIFY_CATALOG_VARIANTS","Partial import",java.time.Instant.EPOCH);assertThat(stopped.terminal()).isTrue();}
}
